import numpy as np

def edmd_with_residual(feature_past, feature_next, ridge):
    x = np.asarray(feature_past, dtype=float)
    y = np.asarray(feature_next, dtype=float)
    if ridge == 0:
        operator = y @ np.linalg.pinv(x, rcond=1e-12)
    else:
        operator = np.linalg.solve(x @ x.T + ridge * np.eye(x.shape[0]),
                                   x @ y.T).T
    return [operator.tolist(), float(np.linalg.norm(y - operator @ x, ord='fro'))]

def solve(feature_past, feature_next, ridge):
    return edmd_with_residual(feature_past, feature_next, ridge)
